      body: batch,
      schema: runEventsAccepted,
    })
  }

  async checkpointRun(runId: string, checkpoint: RunCheckpoint) {
    await this.call("POST", devicePaths.runCheckpoint(checkId(runId)), {
      body: checkpoint,
    })
  }

  async updateRun(runId: string, patch: RunPatch) {
